"""
Ultimate LLM Engine – single-file backend  
API-first, Cerebras-prioritású több-provider motor, RAG, webkeresés, JWT-auth.

Környezeti változók (.env): a korábban felsorolt API-kulcsok KÖTELEZŐK.
Futtatás:  uvicorn backend:app --host 0.0.0.0 --port 7860
"""

import os, json, time, secrets, string, sqlite3, asyncio, hashlib
from datetime import datetime, timedelta
from typing import List, Dict, Any, Optional, AsyncGenerator
from contextlib import asynccontextmanager

from fastapi import (
    FastAPI, HTTPException, Depends, WebSocket, WebSocketDisconnect,
    UploadFile, File, BackgroundTasks
)
from fastapi.middleware.cors import CORSMiddleware
from fastapi.middleware.gzip import GZipMiddleware
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials, OAuth2PasswordRequestForm
from fastapi.responses import StreamingResponse, FileResponse
from pydantic import BaseModel
from pydantic_settings import BaseSettings
from passlib.context import CryptContext
from jose import jwt, JWTError
import httpx, numpy as np
from sentence_transformers import SentenceTransformer
from cerebras_cloud import Cerebras
import openai, google.generativeai as genai
from dotenv import load_dotenv

# ───────────────────────  CONFIG  ───────────────────────
load_dotenv(".env")

class Settings(BaseSettings):
    EXA_API_KEY: str
    OPENAI_API_KEY: str
    OPENAI_ORG_ID: str
    OPENAI_ADMIN_KEY: str
    GOOGLE_AI_API_KEY: str
    GEMINI_API_KEY: str
    GCP_SERVICE_ACCOUNT_KEY: str
    CEREBRAS_API_KEY: str
    ALPHAGENOME_API_KEY: str
    GITHUB_TOKEN: str
    JINA_AI_API_KEY: str
    PINECONE_API_KEY: str
    PERPLEXITY_API_KEY: str
    VESPA_API_KEY: str
    BRAVE_API_KEY: str
    TAVILY_API_KEY: str
    PORTKEY_API_KEY: str
    PORTKEY_VIRTUAL_KEY: str

    SECRET_KEY: str = "change-me"
    ALGORITHM: str = "HS256"
    TOKEN_EXP_MIN: int = 30
    DB_PATH: str = "ultimate_llm.db"

    class Config:
        env_file = ".env"

settings = Settings()

# ───────────────────  SECURITY / AUTH  ───────────────────
pwd_ctx = CryptContext(schemes=["bcrypt"], deprecated="auto")
bearer = HTTPBearer()

def hash_pwd(p: str) -> str: return pwd_ctx.hash(p)
def verify_pwd(p: str, h: str) -> bool: return pwd_ctx.verify(p, h)
def jwt_encode(data, exp_min=None):
    payload = data.copy()
    payload["exp"] = datetime.utcnow() + timedelta(minutes=exp_min or settings.TOKEN_EXP_MIN)
    return jwt.encode(payload, settings.SECRET_KEY, algorithm=settings.ALGORITHM)
def jwt_decode(token):
    return jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])

# ─────────────────────  DATABASE  ─────────────────────
def init_db():
    con = sqlite3.connect(settings.DB_PATH); cur = con.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS users(
        id INTEGER PRIMARY KEY, username TEXT UNIQUE, email TEXT UNIQUE,
        pwd TEXT, admin INT DEFAULT 0, active INT DEFAULT 1,
        api_key TEXT UNIQUE, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS sessions(
        id INTEGER PRIMARY KEY, user_id INT, sid TEXT, model TEXT, provider TEXT,
        msgs TEXT, tokens INT, cost REAL, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS docs(
        id INTEGER PRIMARY KEY, user_id INT, name TEXT, content TEXT,
        embed TEXT, meta TEXT, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""")
    con.commit(); con.close()

def db():  # context helper
    con = sqlite3.connect(settings.DB_PATH)
    con.row_factory = sqlite3.Row
    try: yield con
    finally: con.close()

# ─────────────────────  PROVIDERS  ─────────────────────
openai.api_key, openai.organization = settings.OPENAI_API_KEY, settings.OPENAI_ORG_ID
genai.configure(api_key=settings.GOOGLE_AI_API_KEY)
cb_client = Cerebras(api_key=settings.CEREBRAS_API_KEY)
embedding_model = SentenceTransformer("all-MiniLM-L6-v2")

MODEL_MAP = {
    "qwen3-32b": ("cerebras", "qwen3-32b"),
    "qwen3-235b": ("cerebras", "qwen3-235b"),
    "llama-3.1-8b": ("cerebras", "llama-3.1-8b"),
    "llama-3.3-70b": ("cerebras", "llama-3.3-70b"),
    "llama-4-scout": ("cerebras", "llama-4-scout"),
    "llama-4-maverick": ("cerebras", "llama-4-maverick"),
    "deepseek-r1-llama-70b": ("cerebras", "deepseek-r1-llama-70b"),
    "gpt-4": ("openai", "gpt-4"), "gpt-3.5-turbo": ("openai", "gpt-3.5-turbo"),
    "gemini-pro": ("google", "gemini-pro")
}
PROVIDERS = ["cerebras", "openai", "google", "perplexity"]

async def call_provider(provider, model, msgs, stream=False, **kw):
    if provider == "cerebras":
        if stream:
            res = cb_client.chat.completions.create(model=model, messages=msgs, stream=True, **kw)
            async for c in res: yield c
        else:
            return cb_client.chat.completions.create(model=model, messages=msgs, **kw)
    elif provider == "openai":
        if stream:
            res = openai.ChatCompletion.create(model=model, messages=msgs, stream=True, **kw)
            for c in res: yield c
        else:
            return openai.ChatCompletion.create(model=model, messages=msgs, **kw)
    elif provider == "google":
        content = "\n".join(f"{m['role']}: {m['content']}" for m in msgs)
        m = genai.GenerativeModel(model)
        if stream:
            for c in m.generate_content(content, stream=True, **kw): yield c
        else:
            return m.generate_content(content, **kw)
    else:  # perplexity simple call
        async with httpx.AsyncClient() as cli:
            r = await cli.post("",
                               headers={"Authorization": f"Bearer {settings.PERPLEXITY_API_KEY}"},
                               json={"model": model, "messages": msgs, "stream": stream, **kw})
            return r.json()

# ─────────────────────  HELPERS  ─────────────────────
def gen_api_key(): return ''.join(secrets.choice(string.ascii_letters+string.digits) for _ in range(32))
def embedding(text): return embedding_model.encode(text).tolist()
def cosine(a,b): return float(np.dot(a,b)/(np.linalg.norm(a)*np.linalg.norm(b)))

# ─────────────────────  FASTAPI APP  ─────────────────────
@asynccontextmanager
async def life(app: FastAPI):
    init_db()
    # ensure default admin
    with next(db()) as con:
        cur = con.cursor()
        cur.execute("SELECT 1 FROM users WHERE username='admin'")
        if not cur.fetchone():
            cur.execute("INSERT INTO users(username,email,pwd,admin,api_key) VALUES(?,?,?,?,?)",
                        ("admin","admin@local",hash_pwd("admin123"),1,gen_api_key()))
            con.commit()
    yield

app = FastAPI(title="Ultimate LLM Engine", version="4.0", lifespan=life)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])
app.add_middleware(GZipMiddleware, minimum_size=1000)

# ─────────────────────  SCHEMAS  ─────────────────────
class SignUp(BaseModel): username:str; email:str; password:str
class Token(BaseModel): access_token:str; token_type:str="bearer"
class ChatReq(BaseModel):
    messages: List[Dict[str,str]]
    model:str="qwen3-235b"; stream:bool=False
    temperature:float=0.7; max_tokens:int=4000
class RAGReq(BaseModel): query:str; model:str="qwen3-235b"; top_k:int=5

# ─────────────────────  AUTH DEPS  ─────────────────────
def user_dep(token:HTTPAuthorizationCredentials=Depends(bearer)):
    try:
        payload=jwt_decode(token.credentials)
        uname=payload.get("sub"); assert uname
    except Exception: raise HTTPException(401,"Invalid token")
    with next(db()) as con:
        cur=con.cursor(); cur.execute("SELECT * FROM users WHERE username=?", (uname,))
        u=cur.fetchone()
        if not u or not u["active"]: raise HTTPException(401,"Inactive user")
        return dict(u)

# ─────────────────────  AUTH ROUTES  ─────────────────────
@app.post("/auth/register", response_model=Token)
def register(body:SignUp):
    with next(db()) as con:
        cur=con.cursor()
        if cur.execute("SELECT 1 FROM users WHERE username=?",(body.username,)).fetchone():
            raise HTTPException(400,"Username taken")
        cur.execute("INSERT INTO users(username,email,pwd,api_key) VALUES(?,?,?,?)",
                    (body.username,body.email,hash_pwd(body.password),gen_api_key()))
        con.commit()
    return login(OAuth2PasswordRequestForm(username=body.username,password=body.password,scope=""))

@app.post("/auth/login", response_model=Token)
def login(form_data:OAuth2PasswordRequestForm=Depends()):
    with next(db()) as con:
        cur=con.cursor(); cur.execute("SELECT * FROM users WHERE username=?", (form_data.username,))
        u=cur.fetchone()
        if not u or not verify_pwd(form_data.password,u["pwd"]):
            raise HTTPException(401,"Bad credentials")
    return {"access_token":jwt_encode({"sub":u["username"]}),"token_type":"bearer"}

# ─────────────────────  CHAT  ─────────────────────
@app.post("/llm/chat")
async def chat(req:ChatReq, user=Depends(user_dep)):
    prov, model_id = MODEL_MAP.get(req.model, ("cerebras","qwen3-235b"))
    sid = f"{user['id']}_{int(time.time())}"
    if req.stream:
        async def gen():
            tokens=0
            async for ch in call_provider(prov,model_id,req.messages,stream=True,temperature=req.temperature,max_tokens=req.max_tokens):
                tokens+=1
                yield f"data:{json.dumps(ch)}\n\n"
            with next(db()) as con:
                con.execute("INSERT INTO sessions(user_id,sid,model,provider,msgs,tokens,cost) VALUES(?,?,?,?,?,?,?)",
                            (user["id"],sid,req.model,prov,json.dumps(req.messages),tokens,tokens*0.0001)); con.commit()
            yield "data:[DONE]\n\n"
        return StreamingResponse(gen(),media_type="text/plain")
    else:
        res = await call_provider(prov,model_id,req.messages,temperature=req.temperature,max_tokens=req.max_tokens)
        tokens=len(str(res).split())
        with next(db()) as con:
            con.execute("INSERT INTO sessions(user_id,sid,model,provider,msgs,tokens,cost) VALUES(?,?,?,?,?,?,?)",
                        (user["id"],sid,req.model,prov,json.dumps(req.messages),tokens,tokens*0.0001)); con.commit()
        return {"provider":prov,"model":req.model,"result":res,"session_id":sid,"tokens":tokens}

# ─────────────────────  DOCUMENTS / RAG  ─────────────────────
@app.post("/rag/upload")
async def upload(file:UploadFile=File(...), user=Depends(user_dep)):
    txt = (await file.read()).decode()
    emb = json.dumps(embedding(txt))
    with next(db()) as con:
        cur=con.cursor()
        cur.execute("INSERT INTO docs(user_id,name,content,embed,meta) VALUES(?,?,?,?,?)",
                    (user["id"],file.filename,txt,emb,json.dumps({"type":file.content_type})))
        con.commit(); doc_id=cur.lastrowid
    return {"doc_id":doc_id,"status":"stored"}

@app.post("/rag/query")
async def rag(req:RAGReq, user=Depends(user_dep)):
    q_emb = embedding(req.query)
    with next(db()) as con:
        cur=con.cursor(); cur.execute("SELECT id,name,content,embed FROM docs WHERE user_id=?", (user["id"],))
        docs=[]
        for d in cur.fetchall():
            sim=cosine(q_emb,json.loads(d["embed"]))
            docs.append((sim,d))
    docs.sort(reverse=True,key=lambda x:x[0]); top=docs[:req.top_k]
    ctxt="\n\n".join(f"Doc{i+1}:{d[1]['content'][:500]}" for i,d in enumerate(top))
    msgs=[{"role":"system","content":f"Use context:\n{ctxt}"},{"role":"user","content":req.query}]
    resp=await call_provider(*MODEL_MAP.get(req.model),msgs)
    return {"answer":str(resp),"sources":[{"id":d[1]["id"],"score":d[0]} for d in top]}

# ─────────────────────  SEARCH  ─────────────────────
async def exa(q,n):
    import exa_py; e=exa_py.Exa(api_key=settings.EXA_API_KEY)
    r=e.search(query=q,num_results=n,include_content=True)
    return [{"url":x.url,"title":x.title,"snippet":x.content[:160]} for x in r.results]

async def brave(q,n):
    async with httpx.AsyncClient() as c:
        r=await c.get("",
                      headers={"X-Subscription-Token":settings.BRAVE_API_KEY},params={"q":q,"count":n})
        if r.status_code!=200: return []
        return [{"url":x["url"],"title":x["title"],"snippet":x["description"]} for x in r.json().get("web",{}).get("results",[])]

async def tavily(q,n):
    async with httpx.AsyncClient() as c:
        r=await c.post("",json={"api_key":settings.TAVILY_API_KEY,"query":q,"max_results":n,"include_content":True})
        if r.status_code!=200:return []
        return [{"url":x["url"],"title":x["title"],"snippet":x["content"][:160]} for x in r.json().get("results",[])]

@app.get("/search")
async def web(q:str, n:int=10, user=Depends(user_dep)):
    res=await asyncio.gather(exa(q,n),brave(q,n),tavily(q,n))
    seen,final=[],[]
    for lst in res:
        for r in lst:
            if r["url"] not in seen:
                seen.append(r["url"]); final.append(r)
    return {"total":len(final),"results":final[:n]}

# ─────────────────────  STATIC FRONTEND  ─────────────────────
@app.get("/app", response_class=FileResponse)
def app_file(): return FileResponse("frontend.html", media_type="text/html")

# ─────────────────────  WEBSOCKET  ─────────────────────
class ConnMgr: conns:dict={}
mgr=ConnMgr()
@app.websocket("/ws/{cid}")
async def ws(ws:WebSocket,cid:str):
    await ws.accept(); mgr.conns[cid]=ws
    try:
        while True:
            data=json.loads(await ws.receive_text())
            if data.get("type")=="chat":
                async for ch in call_provider(*MODEL_MAP["qwen3-32b"],data["messages"],stream=True):
                    await ws.send_text(json.dumps(ch))
    except WebSocketDisconnect:
        mgr.conns.pop(cid,None)

# ─────────────────────  ROOT  ─────────────────────
@app.get("/")
def root(): return {"name":"Ultimate LLM Engine","version":"4.0"}
```

