<!DOCTYPE html>
<html lang="hu">
<head>
<meta charset="UTF-8" />
<title>Ultimate LLM Frontend</title>
<style>
body{font-family:Arial;margin:0;background:#f5f5f5;color:#333}
.container{max-width:900px;margin:auto;padding:20px}
.card{background:#fff;padding:20px;margin:10px 0;border-radius:8px;box-shadow:0 2px 4px rgba(0,0,0,.1)}
input,button,textarea{width:100%;padding:10px;margin:5px 0;border:1px solid #ccc;border-radius:4px}
button{background:#007bff;color:#fff;border:none;cursor:pointer}
button:hover{background:#0056b3}
.msg{margin:5px 0;padding:10px;border-radius:6px}
.user{background:#d1e7dd}
.ai{background:#e2e3e5}
</style>
</head>
<body>
<div class="container">
<h1>Ultimate LLM Engine – Web UI</h1>

<div id="auth" class="card">
<h3>Bejelentkezés</h3>
<input id="user" placeholder="felhasználónév">
<input id="pass" placeholder="jelszó" type="password">
<button onclick="login()">Login</button>
<small id="authmsg"></small>
</div>

<div id="chatbox" class="card" style="display:none">
<h3>Csevegés</h3>
<div id="msgs" style="height:300px;overflow-y:auto;border:1px solid #ddd;padding:10px"></div>
<textarea id="input" rows="3" placeholder="Írj ide..."></textarea>
<button onclick="send()">Küldés</button>
</div>
</div>

<script>
let token="";
function login(){
  fetch("/auth/login",{
    method:"POST",
    headers:{"Content-Type":"application/x-www-form-urlencoded"},
    body:new URLSearchParams({username:document.getElementById('user').value,password:document.getElementById('pass').value})
  }).then(r=>r.json()).then(d=>{
      if(d.access_token){ token=d.access_token;
        document.getElementById('auth').style.display='none';
        document.getElementById('chatbox').style.display='block';
      }else document.getElementById('authmsg').innerText='Hiba!';
  });
}
function add(role,text){
  const div=document.createElement('div');
  div.className='msg '+role; div.textContent=text;
  document.getElementById('msgs').appendChild(div);
  document.getElementById('msgs').scrollTop=99999;
}
async function send(){
  const txt=document.getElementById('input').value; if(!txt)return;
  add('user',txt); document.getElementById('input').value='';
  const res=await fetch("/llm/chat",{method:"POST",
    headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},
    body:JSON.stringify({messages:[{role:"user",content:txt}],stream:false})
  }).then(r=>r.json());
  add('ai',res.result.choices?res.result.choices[0].message.content:res.result);
}
</script>
</body>
</html>
